package ledger;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public record Journal(List<Transaction> transactions) {

  public static Journal parse(String source) {
    List<Transaction> transactions = new ArrayList<>();
    LocalDate date = null;
    String payee = null;
    List<Posting> postings = new ArrayList<>();

    for (String line : source.lines().toList()) {
      if (line.isBlank()) {
        continue;
      }
      if (Character.isWhitespace(line.charAt(0))) {
        postings.add(parsePosting(line.trim()));
      } else {
        if (date != null) {
          transactions.add(new Transaction(date, payee, infer(postings)));
          postings = new ArrayList<>();
        }
        String[] head = line.split("\\s+", 2);
        date = LocalDate.parse(head[0]);
        payee = head[1];
      }
    }
    if (date != null) {
      transactions.add(new Transaction(date, payee, infer(postings)));
    }
    return new Journal(transactions);
  }

  private static Posting parsePosting(String line) {
    String[] fields = line.split("\\s\\s+|\\t+", 2);
    if (fields.length == 1) {
      return new Posting(fields[0], null);
    }
    String[] amount = fields[1].trim().split("\\s+");
    return new Posting(fields[0], new Amount(new BigDecimal(amount[0]), amount[1]));
  }

  /** Fills in the amount of the single posting that omitted one, from the others' total. */
  private static List<Posting> infer(List<Posting> postings) {
    Map<String, BigDecimal> totals = new LinkedHashMap<>();
    int elided = -1;
    for (int i = 0; i < postings.size(); i++) {
      Amount amount = postings.get(i).amount();
      if (amount == null) {
        elided = i;
      } else {
        totals.merge(amount.currency(), amount.value(), BigDecimal::add);
      }
    }
    if (elided < 0 || totals.size() != 1) {
      return postings;
    }
    Map.Entry<String, BigDecimal> total = totals.entrySet().iterator().next();
    List<Posting> filled = new ArrayList<>(postings);
    filled.set(
        elided,
        new Posting(postings.get(elided).account(), new Amount(total.getValue().negate(), total.getKey())));
    return filled;
  }
}
