package ledger;

import java.io.IOException;
import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public record Journal(List<Transaction> transactions, List<LedgerError> errors) {

  public static Journal parse(String source) {
    Parser parser = new Parser();
    parser.read(source, "<input>", null);
    return new Journal(parser.transactions, parser.errors);
  }

  public static Journal parse(Path file) throws IOException {
    Parser parser = new Parser();
    parser.read(Files.readString(file), file.toString(), file.toAbsolutePath().getParent());
    return new Journal(parser.transactions, parser.errors);
  }

  private static final class Parser {
    private final List<Transaction> transactions = new ArrayList<>();
    private final List<LedgerError> errors = new ArrayList<>();

    private void read(String source, String file, Path directory) {
      LocalDate date = null;
      String payee = null;
      int headerLine = 0;
      List<Posting> postings = new ArrayList<>();

      int lineNumber = 0;
      for (String raw : source.lines().toList()) {
        lineNumber++;
        String line = stripComment(raw);
        if (line.isBlank()) {
          continue;
        }
        if (Character.isWhitespace(line.charAt(0))) {
          postings.add(parsePosting(line.strip()));
          continue;
        }
        if (date != null) {
          close(date, payee, postings, file, headerLine);
          date = null;
        }
        postings = new ArrayList<>();
        if (line.startsWith("include ")) {
          include(line.substring("include ".length()).strip(), file, lineNumber, directory);
          continue;
        }
        String[] head = line.strip().split("\\s+", 2);
        date = LocalDate.parse(head[0]);
        payee = head[1];
        headerLine = lineNumber;
      }
      if (date != null) {
        close(date, payee, postings, file, headerLine);
      }
    }

    private void include(String name, String file, int line, Path directory) {
      Path included = directory == null ? Path.of(name) : directory.resolve(name);
      try {
        read(Files.readString(included), name, included.toAbsolutePath().getParent());
      } catch (IOException e) {
        errors.add(new LedgerError(file, line, "cannot read included file: " + name));
      }
    }

    private void close(
        LocalDate date, String payee, List<Posting> postings, String file, int line) {
      List<Posting> filled = infer(postings);
      transactions.add(new Transaction(date, payee, filled, line));
      if (filled.stream().anyMatch(posting -> posting.amount() == null)) {
        // ponytail: one elided posting cannot absorb several currencies at once; allowing that
        // would mean several amounts per posting. Report it instead.
        errors.add(
            new LedgerError(
                file,
                line,
                "cannot infer an amount: the transaction spans "
                    + String.join(", ", totals(filled).keySet())));
        return;
      }
      String residual = residual(filled);
      if (!residual.isEmpty()) {
        errors.add(new LedgerError(file, line, "transaction does not balance: " + residual));
      }
    }
  }

  private static String stripComment(String line) {
    int comment = line.indexOf(';');
    return comment < 0 ? line : line.substring(0, comment);
  }

  private static Posting parsePosting(String line) {
    String[] fields = line.split("\\s\\s+|\\t+", 2);
    if (fields.length == 1) {
      return new Posting(fields[0], null);
    }
    String[] amount = fields[1].strip().split("\\s+");
    return new Posting(fields[0], new Amount(new BigDecimal(amount[0]), amount[1]));
  }

  /** Fills in the amount of the single posting that omitted one, from the others' total. */
  private static List<Posting> infer(List<Posting> postings) {
    Map<String, BigDecimal> totals = totals(postings);
    int elided = -1;
    for (int i = 0; i < postings.size(); i++) {
      if (postings.get(i).amount() == null) {
        elided = i;
      }
    }
    if (elided < 0 || totals.size() != 1) {
      return postings;
    }
    Map.Entry<String, BigDecimal> total = totals.entrySet().iterator().next();
    List<Posting> filled = new ArrayList<>(postings);
    filled.set(
        elided,
        new Posting(
            postings.get(elided).account(), new Amount(total.getValue().negate(), total.getKey())));
    return filled;
  }

  private static Map<String, BigDecimal> totals(List<Posting> postings) {
    Map<String, BigDecimal> totals = new LinkedHashMap<>();
    for (Posting posting : postings) {
      if (posting.amount() != null) {
        totals.merge(posting.amount().currency(), posting.amount().value(), BigDecimal::add);
      }
    }
    return totals;
  }

  /** The non-zero remainder of a transaction, rendered for a message; empty when it balances. */
  private static String residual(List<Posting> postings) {
    List<String> parts = new ArrayList<>();
    for (Map.Entry<String, BigDecimal> total : totals(postings).entrySet()) {
      if (total.getValue().signum() != 0) {
        parts.add(total.getValue().toPlainString() + " " + total.getKey());
      }
    }
    return String.join(", ", parts);
  }
}
